# Generated by Selenium IDE & Refined for NextHire AI
import os
import time
import pytest
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC


class TestResume:
    def setup_method(self, method):
        options = webdriver.ChromeOptions()
        options.add_argument("--disable-search-engine-choice-screen")
        options.add_argument("--disable-notifications")
        options.add_argument("--start-maximized")

        self.driver = webdriver.Chrome(options=options)
        self.wait = WebDriverWait(self.driver, 15)
        self.long_wait = WebDriverWait(self.driver, 60)
        self.vars = {}

    def teardown_method(self, method):
        if hasattr(self, "driver") and self.driver:
            self.driver.quit()

    def test_resume(self):
        driver = self.driver

        # 1. Open Sign-In page
        driver.get("http://localhost:5173/sign-in")

        # 2. Enter login credentials
        email_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "signin-email"))
        )
        email_field.clear()
        email_field.send_keys("maria@gmail.com")

        password_field = self.wait.until(
            EC.visibility_of_element_located((By.ID, "signin-password"))
        )
        password_field.clear()
        password_field.send_keys("maria@123")
        password_field.send_keys(Keys.ENTER)

        # 3. Wait for login to complete and dashboard to load
        sidebar_resume = self.wait.until(
            EC.element_to_be_clickable((By.ID, "sidebar-resume"))
        )
        sidebar_resume.click()

        # 4. Wait for Resume Analyzer page to load
        self.wait.until(
            EC.url_contains("/resume-analyzer")
        )

        # 5. Resolve real resume file path dynamically
        possible_paths = [
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "ROSE FINAL RESUME (1) (1).docx"),
            r"C:\Users\andre\Desktop\Testing\ROSE FINAL RESUME (1) (1).docx",
            r"C:\Users\andre\Downloads\ROSE FINAL RESUME (1) (1).docx",
            os.path.join(os.path.expanduser("~"), "Downloads", "ROSE FINAL RESUME (1) (1).docx"),
        ]
        resume_path = next((p for p in possible_paths if os.path.exists(p)), None)
        assert resume_path is not None, "Resume file 'ROSE FINAL RESUME (1) (1).docx' not found!"

        # 6. Upload file directly to input without opening OS file dialog
        file_input = self.wait.until(
            EC.presence_of_element_located((By.ID, "resume-file-input"))
        )
        file_input.send_keys(resume_path)

        # Wait until file selection is acknowledged by the UI
        self.wait.until(
            EC.presence_of_element_located((By.ID, "remove-file-btn"))
        )

        # 7. Click Analyze Resume button
        analyze_btn = self.wait.until(
            EC.element_to_be_clickable((By.ID, "analyze-resume-btn"))
        )
        analyze_btn.click()

        # 8. Wait for AI analysis results to load
        self.long_wait.until(
            EC.visibility_of_element_located((By.ID, "analyze-another-btn"))
        )

        assert driver.find_element(By.ID, "analyze-another-btn").is_displayed()
